window.VOCAB_LWS_META = [{"batch":2,"added":"2026-11-07","lesson":1,"lesson_title":"Glück im Alltag","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 171–175","tips":[{"text":"Das Wort *als* hat mehrere Bedeutungen. Schreiben Sie zu jeder Bedeutung einen Satz.","text_en":"Le mot *als* a plusieurs sens. Écrivez une phrase pour chaque sens.","example":"Wann? Als ich drei Jahre alt war, bekam ich mein erstes Haustier.","answer":["Vergleich: Jan ist älter als Julian","Berufsbezeichnung: Er arbeitet als Arzt"],"note":"Trois sens : *als* = quand, lorsque (un seul événement dans le passé, verbe à la fin) ; *als* après un comparatif = que ; *als* + métier ou rôle = comme, en tant que. Pour quelque chose qui s'est répété plusieurs fois dans le passé, utilisez *wenn*, pas *als*."}],"count":78},{"batch":3,"added":"2026-11-07","lesson":2,"lesson_title":"Unterhaltung","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 175–179","tips":[{"text":"Schreiben Sie eine kleine Geschichte mit den Wörtern aus der Lektion.","text_en":"Écrivez une petite histoire avec les mots de la leçon.","example":"Meine Geschichte handelt von einem unglaublichen Abenteuer: Ich begegnete in einer grossen Stadt dem Star aus meiner Lieblingsserie. Unglaublich! Ich war optimistisch, dass …","answer":["… ich ein Foto mit ihm machen kann. Ich hatte zwar nicht den Mut, ihn anzusprechen, aber dann kam die grosse Überraschung: Er fragte mich, wo der Bahnhof ist!"],"note":"Un modèle de réponse ; la vôtre peut être très différente. En français : « … que j'ai pu prendre une photo avec lui. Je n'ai certes pas eu le courage de lui parler, mais ensuite est venue la grande surprise : il m'a demandé où était la gare ! » Elle réutilise *zwar … aber*, *der Mut* et *die Überraschung* de la Lektion 1."}],"count":66},{"batch":4,"added":"2026-11-07","lesson":3,"lesson_title":"Gesund bleiben","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 179–183","tips":[{"text":"Lernen Sie typische Wendungen zusammen.","text_en":"Apprenez ensemble des expressions typiques.","example":"den Blutdruck messen, Blut abnehmen, das Gewicht prüfen, den Bauch …","answer":["den Bauch untersuchen","jemanden impfen","Medikamente verschreiben","jemanden krankschreiben","ein Gespräch führen","einen Termin vereinbaren","Sport treiben","auf Schokolade verzichten"],"note":"*den Bauch untersuchen* complète la liste du livre (examiner le ventre). Les autres sont des paires de mots de cette leçon à apprendre comme un tout : se faire vacciner, prescrire des médicaments, mettre quelqu'un en arrêt maladie, avoir une conversation, prendre rendez-vous, faire du sport, renoncer au chocolat."}],"count":68},{"batch":1,"added":"2026-11-06","lesson":4,"lesson_title":"Sprachen","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 184–187","tips":[{"text":"Im Deutschen enden viele Sprachen auf «-isch». Schreiben Sie.","text_en":"En allemand, beaucoup de noms de langues se terminent en -isch. Écrivez-en quelques-uns.","example":"Griechisch, Französisch, …","answer":["Englisch","Spanisch","Italienisch","Portugiesisch","Russisch","Polnisch","Türkisch","Arabisch","Chinesisch","Japanisch","Ungarisch","Albanisch"],"note":"Les noms de langues sont neutres et s'emploient en général sans article : *Ich lerne Spanisch.* Toutes les langues ne se terminent pas en *-isch* : *Deutsch*, *Hindi* et *Swahili*, par exemple."}],"count":60},{"batch":5,"added":"2026-11-09","lesson":5,"lesson_title":"Eine Arbeit finden","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 188–191","tips":[{"text":"Notieren Sie einen Beruf. Bilden Sie mit seinen Buchstaben einen Satz.","text_en":"Notez un métier. Formez une phrase avec ses lettres.","example":"Maler: *M*ein *A*rzt *l*iest *e*inen *R*eiseführer.","answer":["Arzt: Anna ruft zwei Taxis","Lehrer: Lara erklärt heute Ronja einen Roman"],"note":"Chaque mot commence par la lettre suivante du métier. Toute phrase qui fonctionne est juste."}],"count":53},{"batch":6,"added":"2026-11-09","lesson":6,"lesson_title":"Dienstleistung","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 191–195","tips":[{"text":"Bilden Sie mit den Buchstaben von einem langen Wort neue Wörter.","text_en":"Formez de nouveaux mots avec les lettres d'un mot long.","example":"Bedienungsanleitung: laut, Dienstag, Tal, …","answer":["Bad","Geld","Insel","Nadel","Lied","Sieg","Tanne","Leben"],"note":"Utilisez chaque lettre de *Bedienungsanleitung* au maximum autant de fois qu'elle apparaît dans le mot."}],"count":66},{"batch":7,"added":"2026-11-09","lesson":7,"lesson_title":"Rund ums Wohnen","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 196–200","tips":[{"text":"Leiten Sie unbekannte Wörter von bekannten Wörtern ab.","text_en":"Déduisez les mots inconnus à partir de mots que vous connaissez.","example":"unaufmerksam = nicht aufmerksam","answer":["unverständlich = nicht verständlich","ungemütlich = nicht gemütlich","friedlich = ohne Streit, voller Frieden","der Stadtrand = der Rand der Stadt","das Fernsehverbot = das Verbot, fernzusehen"],"note":"*un-* transforme un adjectif en son contraire ; un nom composé s'explique par sa dernière partie."}],"count":67}];
